<script>
(function(){
  var sel=document.getElementById('fornecedor_produto_id');
  var novo=document.getElementById('novo_fornecedor_produto');
  if(sel&&novo){
    function atualiza(){
      var isNovo=sel.value==='NOVO';
      novo.required=isNovo;
      novo.disabled=!isNovo;
      if(!isNovo) novo.value='';
      novo.placeholder=isNovo?'Digite o nome do novo fornecedor':'Selecione “+ Cadastrar novo fornecedor” para informar um novo';
    }
    sel.addEventListener('change',atualiza);
    atualiza();
  }
  document.querySelectorAll('.transfer-form').forEach(function(form){
    form.addEventListener('submit',function(e){
      var input=form.querySelector('input[name="quantidade"]');
      var max=parseFloat(form.getAttribute('data-max')||'0');
      var q=parseFloat(input.value||'0');
      if(q<=0){ e.preventDefault(); alert('Informe a quantidade que foi realmente transferida.'); input.focus(); return; }
      if(q>max+0.000001){ e.preventDefault(); alert('Estoque local não possui a quantidade a ser transferida. Máximo disponível para transferência, preservando o estoque mínimo local: '+max.toLocaleString('pt-BR')+'.'); input.focus(); }
    });
  });

  var fornecedorCompra=document.querySelector('select[name="fornecedor_produto_id"]');
  var produtoCompra=document.getElementById('produto_compra_id');
  if(fornecedorCompra&&produtoCompra){
    function filtraProdutosCompra(){
      var fornecedor=fornecedorCompra.value;
      var atual=produtoCompra.value;
      var encontrou=false;
      Array.prototype.forEach.call(produtoCompra.options,function(opt){
        if(!opt.value) return;
        var mostrar=fornecedor!=='' && fornecedor!=='NOVO' && String(opt.getAttribute('data-fornecedor'))===String(fornecedor);
        opt.hidden=!mostrar;
        opt.disabled=!mostrar;
        if(mostrar && String(opt.value)===String(atual)) encontrou=true;
      });
      if(!encontrou){
        produtoCompra.value='';
        produtoCompra.options[0].text=fornecedor && fornecedor!=='NOVO' ? 'Selecione o produto' : 'Selecione o fornecedor primeiro';
      }
    }
    fornecedorCompra.addEventListener('change',filtraProdutosCompra);
    filtraProdutosCompra();
  }

})();
</script>
